import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const x=JSON.parse('{"title":"物品与装备","description":"","frontmatter":{},"headers":[],"relativePath":"guide/items.md","filePath":"guide/items.md","lastUpdated":1786200137000}'),a={name:"guide/items.md"};function c(n,t,h,s,i,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="物品与装备" tabindex="-1">物品与装备 <a class="header-anchor" href="#物品与装备" aria-label="Permalink to &quot;物品与装备&quot;">​</a></h1><h2 id="物品职责" tabindex="-1">物品职责 <a class="header-anchor" href="#物品职责" aria-label="Permalink to &quot;物品职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>物品</th><th>类型</th><th>职责</th></tr></thead><tbody><tr><td><strong>魔法卡包</strong></td><td>装备</td><td>提供角色魔法技能及各种属性、能力值（如果有）。装备栏有一个魔法卡包栏位。框架提供标准实现 <code>MagicCardPack</code>（预制实体），含魔法技能组、动态矩阵、同频共振、神经校准、勇气指令、灵魂绑定 6 大特性，见 <a href="/guide/prefabricated-entities.html">预制实体 - 魔法卡包</a></td></tr><tr><td><strong>武器</strong></td><td>装备</td><td>通常提供角色额外攻击力，以及各种属性、能力值（如果有），还可能一些特殊效果。装备栏有一个武器栏位</td></tr><tr><td><strong>防具</strong></td><td>装备</td><td>通常提供角色额外物理护甲或者魔法抗性，以及各种属性、能力值（如果有），还可能一些特殊效果。装备栏有一个防具栏位</td></tr><tr><td><strong>鞋子</strong></td><td>装备</td><td>通常提供角色额外行动速度，以及各种属性、能力值（如果有），还可能一些特殊效果。装备栏有一个鞋子栏位</td></tr><tr><td><strong>饰品</strong></td><td>装备</td><td>提供角色各种各样的属性和能力值，还可能有一些特殊效果。装备栏有<strong>两个</strong>饰品栏位，可以装备两个相同的饰品</td></tr><tr><td><strong>消耗品</strong></td><td>道具</td><td>回复能力值或者临时增强属性和能力值的道具，具有<strong>使用次数限制</strong>，因此称作消耗品</td></tr></tbody></table><h2 id="魔法卡与魔法卡包" tabindex="-1">魔法卡与魔法卡包 <a class="header-anchor" href="#魔法卡与魔法卡包" aria-label="Permalink to &quot;魔法卡与魔法卡包&quot;">​</a></h2><p><strong>魔法卡</strong>是魔法的载体：</p><ul><li>每张魔法卡都包含一定的属性和能力值（如果有）和一个魔法技能</li><li>可以用于<strong>合成</strong>魔法卡包，也可以用于<strong>升级</strong>魔法卡包身上现存的魔法的等级</li></ul><p><strong>合成</strong>：将 X 张魔法卡合成一个能为角色提供至多 X 个魔法技能的魔法卡包，同时，魔法卡包继承这些魔法卡的属性和能力值（如果有）。</p><p><strong>升级</strong>：通常直接将魔法卡的魔法等级添加到魔法卡包上相同的魔法的等级上。<strong>不会超过魔法的最高等级。</strong></p><div class="warning custom-block"><p class="custom-block-title">需要外部实现</p><p>魔法卡的合成/升级功能<strong>不在标准库中</strong>，需要外部实现。</p></div><h2 id="武器类型-weapontype" tabindex="-1">武器类型 (WeaponType) <a class="header-anchor" href="#武器类型-weapontype" aria-label="Permalink to &quot;武器类型 (WeaponType)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>武器</th><th>枚举值</th><th>攻击距离</th><th>硬直时间</th><th>基础伤害倍率</th><th>倍率成长</th></tr></thead><tbody><tr><td>单手剑</td><td><code>OneHandedSword</code></td><td>1</td><td>8</td><td>1.00</td><td>0.05</td></tr><tr><td>双手重剑</td><td><code>TwoHandedSword</code></td><td>2</td><td>12</td><td>1.20</td><td>0.06</td></tr><tr><td>弓</td><td><code>Bow</code></td><td>4</td><td>9</td><td>0.90</td><td>0.04</td></tr><tr><td>手枪</td><td><code>Pistol</code></td><td>3</td><td>6</td><td>0.90</td><td>0.03</td></tr><tr><td>步枪</td><td><code>Rifle</code></td><td>5</td><td>11</td><td>1.10</td><td>0.05</td></tr><tr><td>双持短刀</td><td><code>DualDaggers</code></td><td>1</td><td>7</td><td>0.85</td><td>0.04</td></tr><tr><td>法器</td><td><code>Talisman</code></td><td>5</td><td>10</td><td>1.00</td><td>0.05</td></tr><tr><td>法杖</td><td><code>Staff</code></td><td>3</td><td>12</td><td>1.15</td><td>0.04</td></tr><tr><td>长柄</td><td><code>Polearm</code></td><td>2</td><td>10</td><td>0.95</td><td>0.05</td></tr><tr><td>拳套</td><td><code>Gauntlet</code></td><td>1</td><td>8</td><td>1.05</td><td>0.05</td></tr><tr><td>暗器</td><td><code>HiddenWeapon</code></td><td>4</td><td>7</td><td>0.90</td><td>0.05</td></tr></tbody></table><blockquote><p>法杖和法器自动获得<strong>普通攻击附魔</strong>（转为魔法伤害）。</p></blockquote><h2 id="物品类型-itemtype" tabindex="-1">物品类型 (ItemType) <a class="header-anchor" href="#物品类型-itemtype" aria-label="Permalink to &quot;物品类型 (ItemType)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>ID 范围</th><th>栏位</th></tr></thead><tbody><tr><td><code>MagicCardPack</code></td><td>10xxx</td><td>魔法卡包栏 ×1</td></tr><tr><td><code>Weapon</code></td><td>11xxx</td><td>武器栏 ×1</td></tr><tr><td><code>Armor</code></td><td>12xxx</td><td>防具栏 ×1</td></tr><tr><td><code>Shoes</code></td><td>13xxx</td><td>鞋子栏 ×1</td></tr><tr><td><code>Accessory</code></td><td>14xxx</td><td>饰品栏 ×2</td></tr><tr><td><code>Consumable</code></td><td>15xxx</td><td>背包</td></tr><tr><td><code>MagicCard</code></td><td>16xxx</td><td>背包</td></tr><tr><td><code>Collectible</code></td><td>17xxx</td><td>背包</td></tr><tr><td><code>SpecialItem</code></td><td>18xxx</td><td>背包</td></tr><tr><td><code>QuestItem</code></td><td>19xxx</td><td>背包</td></tr><tr><td><code>GiftBox</code></td><td>20xxx</td><td>背包</td></tr><tr><td><code>Others</code></td><td>21xxx</td><td>背包</td></tr></tbody></table><h2 id="品质等级-qualitytype" tabindex="-1">品质等级 (QualityType) <a class="header-anchor" href="#品质等级-qualitytype" aria-label="Permalink to &quot;品质等级 (QualityType)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>品质</th><th>颜色</th><th>枚举值</th></tr></thead><tbody><tr><td>普通</td><td>白</td><td><code>White</code></td></tr><tr><td>优秀</td><td>绿</td><td><code>Green</code></td></tr><tr><td>稀有</td><td>蓝</td><td><code>Blue</code></td></tr><tr><td>史诗</td><td>紫</td><td><code>Purple</code></td></tr><tr><td>传说</td><td>橙</td><td><code>Orange</code></td></tr><tr><td>神话</td><td>红</td><td><code>Red</code></td></tr><tr><td>不朽</td><td>金</td><td><code>Gold</code></td></tr></tbody></table><h2 id="装备栏位-equipslottype" tabindex="-1">装备栏位 (EquipSlotType) <a class="header-anchor" href="#装备栏位-equipslottype" aria-label="Permalink to &quot;装备栏位 (EquipSlotType)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>栏位</th><th>数量</th></tr></thead><tbody><tr><td>魔法卡包</td><td>1</td></tr><tr><td>武器</td><td>1</td></tr><tr><td>防具</td><td>1</td></tr><tr><td>鞋子</td><td>1</td></tr><tr><td>饰品 1</td><td>1</td></tr><tr><td>饰品 2</td><td>1</td></tr></tbody></table>',18)])])}const b=d(a,[["render",c]]);export{x as __pageData,b as default};
